# DK AHT.  Aarhus - Hammel - Thorsø
#
let fa = path("d3.dk.ffh.1");
let ah = path("d3.dk.aht.1");
let ht = path("d3.dk.aht.2");

with detail = 4, railway = :first :pax :removed {
    with link = "point.dk.Aarhus-Hammelbanegården", railway = :station {
        marker(:bottom :de.bf, ah[:aah]);
        station(:top:right_align, ah[:aah] + (1sh, -1sw) + (3dt, -0.5dt),
            span(:bold, "Aarhus Hammelbanegården"), "AHT: 0,0 "
