    }

    with link = "line.dk.AHT" {
        track(:lor,
                ah[:aah, :aah + 200m]
            ..  fa[:aar.yr + 400m, :aar.yr] >> 2.5mo
        );
        with layer = 1 track(:lor :casing,
                fa[:aar.yr + 0.1dl, :aar.yr] >> 2.5mo
            ..  fa[:aar.yt + 0.1dl, :aar.yt] >> 3mo
            ..  ah[:aar.xt + 2mo, :aar.xt + 2.1mo]
        );
        track(
                ah[:aar.xt + 2mo, :vin - 0.49sw]
        );
    }

    with link = "point.dk.Viby-Nord", railway = :station {
